export class QuotaExceededError extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'QuotaExceededError';
    this.code = code;
  }
}

function assertInteger(value, name) {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    throw new TypeError(`${name} must be an integer`);
  }
}

export function createGate({ limit, windowMs, maxWaitMs = 0, parent = null } = {}) {
  assertInteger(limit, 'limit');
  assertInteger(windowMs, 'windowMs');
  assertInteger(maxWaitMs, 'maxWaitMs');
  if (limit <= 0) throw new RangeError('limit must be a positive integer');
  if (windowMs <= 0) throw new RangeError('windowMs must be a positive integer');
  if (maxWaitMs < 0) throw new RangeError('maxWaitMs must not be negative');

  // A standalone gate owns a family: one quota pool shared by itself and
  // every descendant gate. Child gates are linked into the family of the
  // gate passed as `parent`; only the root owns the pool and the window
  // timer, so every gate shares the root's window.
  const isRoot = parent === null;
  const family = isRoot
    ? {
        used: 0, // family units granted in the current window
        gates: [], // root first, then children in creation order
        seq: 0, // arrival-order tiebreak for same-tick acquires
        now: 0, // last observed monotonic millisecond timestamp
        flipping: false, // re-entrancy guard around expiry + allocation
      }
    : parent._family;
  const root = isRoot ? gateApi() : parent._root;

  let usedSelf = 0; // units occupied by this gate (own + borrowed), released or not
  let borrowed = 0; // of usedSelf, units lent by the parent for this window
  let inFlight = 0; // occupied units not yet released and not cleared by a flip
  let waiting = 0; // units currently queued on this gate
  let granted = 0;
  let refused = 0;
  let expired = 0;
  let generation = 0; // bumped on every window flip, invalidates old handles
  const queue = []; // queued requests in arrival order

  const gate = {
    limit,
    queue,
    // Reads and counters used by the root's window-flip machinery.
    get usedSelf() {
      return usedSelf;
    },
    get borrowed() {
      return borrowed;
    },
    get inFlight() {
      return inFlight;
    },
    get generation() {
      return generation;
    },
    resetWindowCounters() {
      usedSelf = 0;
      borrowed = 0;
      inFlight = 0;
      generation += 1;
    },
    addInFlight(units) {
      inFlight += units;
    },
    addWaiting(units) {
      waiting += units;
    },
    subWaiting(units) {
      waiting -= units;
    },
    bumpGranted() {
      granted += 1;
    },
    bumpRefused() {
      refused += 1;
    },
    bumpExpired() {
      expired += 1;
    },
    stats() {
      return { limit, windowMs: root._windowMs, inFlight, waiting, granted, refused, expired };
    },
  };
  family.gates.push(gate);

  function gateApi() {
    return null; // replaced below; exists only so `root` reads naturally above
  }

  // Effective clock: a clamped monotonic view of Date.now(). A backwards
  // jump of the system wall clock can never move time backwards, so an
  // already elapsed window can never become live again, while prolonged
  // event-loop stalls simply surface as a large forward jump.
  function clockNow() {
    const t = Date.now();
    if (t > family.now) family.now = t;
    return family.now;
  }

  function makeHandle(units, gen) {
    let active = true;
    return {
      release() {
        // Repeated release calls are a no-op and never move any statistic.
        if (!active || gen !== generation) return;
        active = false;
        inFlight -= units;
      },
    };
  }

  function poolLimit() {
    // A child may never use more of the shared pool than its own limit.
    return isRoot ? limit : Math.min(limit, root._poolLimit());
  }

  function admit(entry, now) {
    // All-or-nothing admission against the single family pool. A child
    // borrows the shortfall it does not itself own; the grant still may not
    // exceed either the child's limit or the family limit.
    const cap = isRoot ? limit : Math.min(limit, root._poolLimit());
    const ownAvailable = cap - usedSelf;
    let want = entry.units;
    let entryBorrowed = 0;
    if (ownAvailable < want) {
      entryBorrowed = want - ownAvailable;
      // The pool itself is shared, so fitting in the family pool is the
      // only remaining constraint; the cap is enforced above.
    }
    family.used += want;
    usedSelf += want;
    borrowed += entryBorrowed;
    inFlight += want;
    waiting -= want;
    granted += 1;
    clearTimeout(entry.timer);
    entry.resolve(makeHandle(want, generation));
    void now;
  }

  function expireEntry(entry) {
    const index = queue.indexOf(entry);
    if (index === -1) return;
    queue.splice(index, 1);
    clearTimeout(entry.timer);
    waiting -= entry.units;
    expired += 1;
    entry.reject(
      new QuotaExceededError('WAIT_EXPIRED', 'queued request expired before quota was available'),
    );
  }

  // Repeatedly sweep the family's queues until a full pass admits nothing.
  // Within each pass older requests are considered first; a request that
  // does not fit is skipped so it cannot block later requests that do,
  // but while any older request is still queued it keeps the first pick on
  // every later pass, which guarantees it is never starved.
  function drainFamily(now) {
    const gates = family.gates;
    let progress = true;
    while (progress) {
      progress = false;
      for (let g = 0; g < gates.length; g += 1) {
        const q = gates[g].queue;
        for (let i = 0; i < q.length; i += 1) {
          const entry = q[i];
          const cap = gates[g] === family.gates[0] && isRoot
            ? gates[g].limit
            : Math.min(gates[g].limit, root._poolLimit());
          const withinGateCap = entry.units <= cap - gates[g].usedSelf;
          if (entry.units <= root._poolLimit() - family.used && withinGateCap) {
            q.splice(i, 1);
            admitOn(gates[g], entry, now);
            progress = true;
            i -= 1;
          }
        }
      }
    }
  }

  function admitOn(g, entry, now) {
    const cap = g === family.gates[0] && isRoot
      ? g.limit
      : Math.min(g.limit, root._poolLimit());
    const ownAvailable = cap - g.usedSelf;
    let entryBorrowed = 0;
    if (ownAvailable < entry.units) entryBorrowed = entry.units - ownAvailable;
    family.used += entry.units;
    g._grant(entry.units, entryBorrowed, entry, generation, now);
  }

  // Indirection kept on the gate object so the root can admit entries that
  // belong to child gates and update that child's own statistics/handle.
  Object.assign(gate, {
    _grant(units, entryBorrowed, entry, gen, now) {
      usedSelf += units;
      borrowed += entryBorrowed;
      inFlight += units;
      waiting -= units;
      granted += 1;
      clearTimeout(entry.timer);
      entry.resolve(makeHandle(units, gen));
      void now;
    },
  });

  function flip() {
    // Timers due in the same tick and a long event-loop stall are all
    // handled here, once: expiry is computed BEFORE any quota is handed
    // out. The guard also makes flip re-entrancy safe (timers firing
    // synchronously from mocked clocks).
    if (!isRoot || family.flipping) return;
    family.flipping = true;
    try {
      const now = clockNow();
      const gates = family.gates;
      for (let g = 0; g < gates.length; g += 1) {
        const q = gates[g].queue;
        for (let i = q.length - 1; i >= 0; i -= 1) {
          if (q[i].deadline <= now) expireAt(gates[g], q[i]);
        }
      }
      // New window. Clearing occupations - including borrowed ones - only
      // drops the accounting; every handle already admitted keeps running
      // and is simply detached from the new window, so no admitted
      // occupation is ever split or reclaimed mid-flight. The inFlight
      // change lands in the same synchronous step, hence the same stats
      // snapshot sees it.
      family.used = 0;
      for (let g = 0; g < gates.length; g += 1) gates[g].resetWindowCounters();
      drainFamily(now);
    } finally {
      family.flipping = false;
    }
  }

  function expireAt(g, entry) {
    const index = g.queue.indexOf(entry);
    if (index === -1) return;
    g.queue.splice(index, 1);
    clearTimeout(entry.timer);
    g.subWaiting(entry.units);
    g.bumpExpired();
    entry.reject(
      new QuotaExceededError('WAIT_EXPIRED', 'queued request expired before quota was available'),
    );
  }

  // Try to admit immediately; on failure queue (or refuse). Called both by
  // acquire and after a queued entry expires, and kept O(1)-amortized on
  // the acquire/release hot path: the scan here only touches the single
  // arriving request, full sweeps happen at window flips.
  function tryAcquire(units) {
    const cap = poolLimit();
    if (queue.length === 0 && family.used === 0 ? false : false) {
      // unreachable, kept to make the control flow explicit
    }
    // Immediate admission requires no earlier request to be queued
    // anywhere in the family, room in the shared pool, and room within
    // this gate's own cap.
    let familyQueued = 0;
    for (let g = 0; g < family.gates.length; g += 1) {
      familyQueued += family.gates[g].queue.length;
    }
    const poolFree = root._poolLimit() - family.used;
    if (familyQueued === 0 && units <= poolFree && units <= cap - usedSelf) {
      const ownAvailable = cap - usedSelf;
      const entryBorrowed = ownAvailable < units ? units - ownAvailable : 0;
      family.used += units;
      usedSelf += units;
      borrowed += entryBorrowed;
      inFlight += units;
      granted += 1;
      return { ok: true, handle: makeHandle(units, generation) };
    }
    if (maxWaitMs === 0) {
      refused += 1;
      return { ok: false, error: new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded') };
    }
    waiting += units;
    const now = clockNow();
    const entry = {
      units,
      deadline: now + maxWaitMs,
      seq: family.seq += 1,
      timer: null,
      resolve: null,
      reject: null,
    };
    entry.timer = setTimeout(() => {
      expireEntry(entry);
      // Expiry frees no pool units (the request never held any); it only
      // removes a blocker. Letting a later fitting request through is the
      // flip sweep's job; nothing is granted here in the same tick beyond
      // what already fits, preserving arrival-ordered tie breaks.
    }, maxWaitMs);
    if (typeof entry.timer.unref === 'function') entry.timer.unref();
    queue.push(entry);
    return {
      ok: true,
      promise: new Promise((resolve, reject) => {
        entry.resolve = resolve;
        entry.reject = reject;
      }),
    };
  }

  function acquire(units = 1) {
    assertInteger(units, 'units');
    if (units < 1 || units > limit) {
      throw new RangeError(`units must be between 1 and ${limit}`);
    }
    const result = tryAcquire(units);
    if (result.ok && result.handle) return Promise.resolve(result.handle);
    if (result.ok) return result.promise;
    return Promise.reject(result.error);
  }

  function stats() {
    return gate.stats();
  }

  const api = { acquire, stats };
  if (isRoot) {
    const windowTimer = setInterval(flip, windowMs);
    if (typeof windowTimer.unref === 'function') windowTimer.unref();
    Object.assign(api, {
      _family: family,
      _root: api,
      _windowMs: windowMs,
      _poolLimit: () => family.gates[0].limit,
    });
    family.rootApi = api;
  } else {
    Object.assign(api, {
      _family: family,
      _root: root,
      _windowMs: root._windowMs,
      _poolLimit: root._poolLimit,
    });
  }
  return api;
}

