    g.subWaiting(entry.units);
    g.bumpExpired();
    entry.reject(
      new QuotaExceededError('WAIT_EXPIRED', 'queued request expired before quota was available'),
    );
  }

  // Try to admit immediately; on failure queue (or refuse). Called both by
  // acquire and after a queued entry expires, and kept O(1)-amortized on
  // the acquire/release hot path: the scan here only touches the single
  // arriving request, full sweeps happen at window flips.
  function tryAcquire(units) {
    const cap = poolLimit();
    if (queue.length === 0 && family.used === 0 ? false : false) {
      // unreachable, kept to make the control flow explicit
    }
    // Immediate admission requires no earlier request to be queued
    // anywhere in the family, room in the shared pool, and room within
    // this gate's own cap.
    let familyQueued = 0;
    for (let g = 0; g < family.gates.length; g += 1) {
      familyQueued += family.gates[g].queue.length;
    }
    const poolFree = root._poolLimit() - family.used;
    if (familyQueued === 0 && units <= poolFree && units <= cap - usedSelf) {
      const ownAvailable = cap - usedSelf;
      const entryBorrowed = ownAvailable < units ? units - ownAvailable : 0;
      family.used += units;
      usedSelf += units;
      borrowed += entryBorrowed;
      inFlight += units;
      granted += 1;
      return { ok: true, handle: makeHandle(units, generation) };
    }
    if (maxWaitMs === 0) {
      refused += 1;
      return { ok: false, error: new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded') };
    }
    waiting += units;
    const now = clockNow();
    const entry = {
      units,
      deadline: now + maxWaitMs,
      seq: family.seq += 1,
      timer: null,
      resolve: null,
      reject: null,
    };
    entry.timer = setTimeout(() => {
      expireEntry(entry);
      // Expiry frees no pool units (the request never held any); it only
      // removes a blocker. Letting a later fitting request through is the
      // flip sweep's job; nothing is granted here in the same tick beyond
      // what already fits, preserving arrival-ordered tie breaks.
