function assertInteger(value, name) {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    throw new TypeError(`${name} must be an integer`);
  }
}

// Clamped monotonic view of the wall clock. A backwards jump of the system
// clock can never move time backwards here, so an already elapsed window can
// never become live again; a long event-loop stall simply surfaces as one
// large forward jump when the loop gets back to the timer.
function effectiveNow(family) {
  const t = Date.now();
  if (t > family.lastNow) family.lastNow = t;
  return family.lastNow;
}

// One linear scan per window flip, in family-wide arrival order. An entry
// that does not fit is skipped and can never become admissible later in the
// same window (pool usage only grows), but it stays at the front of the
// remaining queue, so at the next flip - when the pool is full again - the
// oldest waiting entry gets the very first pick. That is what keeps any
// request, including a large one behind smaller ones, from being starved.
