    throw new TypeError('parent must be a gate created by createGate');
  }

  const isRoot = parent === null;
  const family = isRoot
    ? {
        poolLimit: limit,
        windowMs,
        poolUsed: 0, // units granted out of the shared pool this window
        queue: [], // all waiting entries of the family, in arrival order
        nodes: [], // root first, then children in creation order
        seq: 0, // arrival-order tiebreak for same-tick acquires
        lastNow: Date.now(),
        flipping: false,
      }
