// Family waiting queue: a doubly-linked list in arrival order, with a scan
// pointer. A forward sweep examines each entry at most once per window: an
// entry that does not fit is left in place and can never become admissible
// later in the same window (pool and gate usage only grow until the next
// flip), while the sweep moves on so younger, fitting requests pass it. New
// arrivals are appended behind the scan pointer, expiries unlink in O(1),
// so the acquire/release hot path is constant-amortized. At every flip the
// scan pointer returns to the head, which gives the oldest waiting entry
// the very first pick of a fresh window - the guarantee that no request,
// however large, is ever starved.
function drainFamily(family) {
  let entry = family.scan;
  family.scan = null; // the sweep always runs through to the tail
  while (entry !== null) {
    const next = entry.next;
    const node = entry.node;
    if (
      entry.units <= family.poolLimit - family.poolUsed &&
      entry.units <= node.cap() - node.used()
    ) {
      unlink(family, entry);
      node.grant(entry);
    }
    entry = next;
  }
}

function appendEntry(family, entry) {
  entry.prev = family.tail;
  entry.next = null;
  if (family.tail !== null) family.tail.next = entry;
  else family.head = entry;
  family.tail = entry;
  // Anything not already examined this window sits ahead of the new entry;
  // if the queue was fully swept the newcomer is the next thing to examine.
  if (family.scan === null) family.scan = entry;
}

function unlink(family, entry) {
  if (entry.prev !== null) entry.prev.next = entry.next;
  else family.head = entry.next;
  if (entry.next !== null) entry.next.prev = entry.prev;
  else family.tail = entry.prev;
  if (family.scan === entry) family.scan = entry.next;
  entry.prev = null;
  entry.next = null;
}

// Expire one queued entry. Returns false if it was already admitted or
// expired. Expiry frees no pool units (the request never held any); it only
// removes a blocker and lets the sweep re-evaluate whoever follows.
function removeEntry(family, entry, node) {
  if (entry.removed) return false;
  entry.removed = true;
  unlink(family, entry);
  clearTimeout(entry.timer);
  node.markExpired(entry);
  return true;
}

