    const order = [];
    const big = gate.acquire(5).then(() => order.push('big'));
    // Big cannot fit for the rest of the window; the smalls cannot either
    // while the pool is full, so they all wait until the flip, where the
    // oldest (big) is picked first.
    const s1 = gate.acquire(2).then(() => order.push('s1'));
    const s2 = gate.acquire(3).then(() => order.push('s2'));
    await new Promise((r) => setTimeout(r, 80));
