    mock.timers.enable({ apis: ['setTimeout', 'setInterval', 'Date'], now: 0 });
    const gate = createGate({ limit: 2, windowMs: 100, maxWaitMs: 100 });
    return (async () => {
      await gate.acquire(2);
      const a = gate.acquire(1);
      const b = gate.acquire(1);
      mock.timers.tick(100);
      await settle();
      const [ea, eb] = await Promise.allSettled([a, b]);
      assert.equal(ea.status, 'rejected');
      assert.equal(eb.status, 'rejected');
      assert.equal(ea.reason.code, 'WAIT_EXPIRED');
      assert.equal(gate.stats().expired, 2);
      assert.equal(gate.stats().granted, 2); // only the initial fill
    })();
  });

  test('a long event-loop block: overdue waiters expire, then the pool is reallocated', () => {
    mock.timers.enable({ apis: ['setTimeout', 'setInterval', 'Date'], now: 0 });
    const gate = createGate({ limit: 2, windowMs: 100, maxWaitMs: 150 });
    return (async () => {
      await gate.acquire(1);
      await gate.acquire(1); // window full
      const shortLived = gate.acquire(1); // deadline 50
      const survivor = gate.acquire(1); // deadline 150
      // The loop stalls past the window; resume in a single batch.
      mock.timers.setTime(100);
      mock.timers.tick(1);
      await settle();
      await assert.rejects(shortLived, (e) => e.code === 'WAIT_EXPIRED');
      const h = await survivor; // admitted from the fresh pool, not expired
      assert.equal(gate.stats().expired, 1);
      assert.equal(gate.stats().inFlight, 1);
      assert.equal(gate.stats().granted, 3);
      h.release();
    })();
  });

  test('clock rollback never revives an elapsed window', () => {
    mock.timers.enable({ apis: ['setTimeout', 'setInterval', 'Date'], now: 0 });
    const gate = createGate({ limit: 1, windowMs: 100 });
    return (async () => {
      const old = await gate.acquire(1);
      mock.timers.setTime(100);
      gate._family._flip(); // window genuinely elapsed
      assert.equal(gate.stats().inFlight, 0);

      // Wall clock jumps backwards before the flip moment.
      mock.timers.setTime(40);
      old.release(); // handle belongs to the closed window: no statistic moves
      assert.equal(gate.stats().inFlight, 0);
      assert.equal(gate.stats().granted, 1);

      // New work is accounted in the current window, never in the revived
      // old one, and the monotonic counters are not reset by the rollback.
      const fresh = await gate.acquire(1);
      assert.equal(gate.stats().inFlight, 1);
      assert.equal(gate.stats().granted, 2);
      fresh.release();
    })();
  });

