    mock.timers.enable({ apis: ['Date'], now: 0 });
    const gate = createGate({ limit: 1, windowMs: 10_000, maxWaitMs: 100 });
    return (async () => {
      await gate.acquire(1);
      const waiter = gate.acquire(1); // deadline 100 in clamped time
      mock.timers.setTime(120); // time genuinely passed the deadline
      gate._family._flip();
      mock.timers.setTime(20); // rolled back well before the deadline
      // Another flip driven while the wall clock is behind: the clamp keeps
      // time at 120, so it must not re-admit or resurrect the expired entry.
      gate._family._flip();
      await settle();
      await assert.rejects(waiter, (e) => e.code === 'WAIT_EXPIRED');
      assert.equal(gate.stats().expired, 1);
    })();
  });
});

