test('rollback cannot un-expire a deadline the clock already reached', () => {
  mock.timers.enable({ apis: ['setTimeout', 'setInterval', 'Date'], now: 0 });
  const gate = createGate({ limit: 1, windowMs: 10_000, maxWaitMs: 100 });
  return (async () => {
    await gate.acquire(1); // window full at t=0
    const waiter = gate.acquire(1); // deadline t=100
    // Real time advances past the deadline (setTime does not fire timers),
    // then the wall clock jumps backwards to t=20.
    mock.timers.setTime(120);
    mock.timers.setTime(20);
    // The flip sees the clamped clock (120), not the rolled-back 20, so the
    // already-reached deadline still expires instead of being granted.
    gate._family._flip();
    await settle();
    await assert.rejects(waiter, (e) => e.code === 'WAIT_EXPIRED');
    assert.equal(gate.stats().expired, 1);
    assert.equal(gate.stats().granted, 1);
  })();
