function drainFamily(family) {
  let entry = family.scan;
  family.scan = null; // a sweep always runs through to the current tail
  while (entry !== null) {
    const next = entry.next;
    // The family pool is the only capacity check at admission time. A
    // child gate whose own slice is exhausted simply borrows the shortfall
    // from the parent side of the same pool, as long as the pool has room
    // and the grant does not take the child above the parent's limit
    // (enforced by the units bound in acquire).
    if (entry.units <= family.poolLimit - family.poolUsed) {
      unlink(family, entry);
      entry.node.grant(entry);
    }
    entry = next;
  }
}

